I'll show you three common approaches to add debounce to a search input:

## 1. **React Hook (Custom)**
```typescript
import { useState, useEffect } from 'react';

function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => clearTimeout(handler);
  }, [value, delay]);

  return debouncedValue;
}

function SearchComponent() {
  const [searchTerm, setSearchTerm] = useState('');
  const debouncedTerm = useDebounce(searchTerm, 500);

  useEffect(() => {
    if (debouncedTerm) {
      fetchSearchResults(debouncedTerm);
    }
  }, [debouncedTerm]);

  return (
    <input
      type="text"
      value={searchTerm}
      onChange={(e) => setSearchTerm(e.target.value)}
      placeholder="Search..."
    />
  );
}
```

## 2. **Using Lodash (Simplest)**
```typescript
import { debounce } from 'lodash';

function SearchComponent() {
  const [results, setResults] = useState([]);

  const handleSearch = debounce(async (query: string) => {
    const data = await fetch(`/api/search?q=${query}`).then(r => r.json());
    setResults(data);
  }, 500);

  return (
    <input
      type="text"
      onChange={(e) => handleSearch(e.target.value)}
      placeholder="Search..."
    />
  );
}
```

## 3. **Vanilla JavaScript**
```javascript
let timeoutId;

const searchInput = document.getElementById('search');
searchInput.addEventListener('input', (e) => {
  clearTimeout(timeoutId);

  timeoutId = setTimeout(() => {
    fetchSearchResults(e.target.value);
  }, 500);
});

async function fetchSearchResults(query) {
  const response = await fetch(`/api/search?q=${query}`);
  const data = await response.json();
  updateResults(data);
}
```

**Key points:**
- **Delay**: 300-500ms is typical for search inputs
- **Approach 1** is best for React with full control
- **Approach 2** is quickest if you're already using lodash
- **Approach 3** works for vanilla JS without dependencies

